// Ví dụ: Bố trí lịch họp (Activity Selection Problem)
// Chọn nhiều cuộc họp nhất mà không bị trùng thời gian
public int MaxActivities(int[] start, int[] end) {
    // Giả sử mảng đã được sắp xếp tăng dần theo thời gian Kết thúc (end)
    int i = 0;
    int count = 1; // Chọn cuộc họp đầu tiên

    for (int j = 1; j < start.Length; j++) {
        // Nếu cuộc họp sau bắt đầu sau khi cuộc họp trước kết thúc
        if (start[j] >= end[i]) {
            count++;
            i = j; // Cập nhật lại cuộc họp đang xét
        }
    }
    return count;
}
